/**
 * Real slides, snapshotted from decks the pipeline actually built.
 *
 * NOT screenshots — this is the DOM those slides render as, lifted out of a
 * built composition by scripts/snapshot-demo-decks.mjs and inlined so the
 * landing can show (and let you edit) genuine output. That matters: the page
 * claims "real elements, never images", so the proof on the page has to be
 * real elements too.
 *
 * Regenerate with:
 *   node scripts/snapshot-demo-decks.mjs <scriptIdA> <scriptIdB>
 *
 * Slides are authored on a 1920×1080 canvas; the landing scales them to fit
 * (see SlideFrame). `bg` / `ink` / `accent` are pulled off the slide for the
 * rail thumbnails so the chips match without re-rendering anything.
 */

export type DemoSlide = {
  /** Scene label from the script — used for rail titles / alt text. */
  label: string;
  /** Canvas background, so the frame matches before the HTML paints. */
  bg: string;
  /** Dominant ink + accent, for the rail thumbnail chips. */
  ink: string;
  accent: string;
  /** The slide's markup, authored at 1920×1080. */
  html: string;
};

export type DemoDeck = {
  id: string;
  /** What this deck demonstrates on the landing. */
  note: string;
  slides: DemoSlide[];
};

